head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > sortHeaderDiv]<br/>sortable=true 인 Header Column 에 정렬 아이콘을 button 요소로 렌더링하여 항상 표시할지 설정합니다.",
    "validation" : [
        "미설정 또는 false 설정 시 정렬 아이콘 영역을 div 요소로 렌더링하고 sortedIconPosition 속성값에 따라 위치가 정해집니다.",
        "true 설정 시 정렬 아이콘 영역을 button 요소로 렌더링하고 Header 값 오른쪽에 항상 표시합니다.",
        "true 설정 + accessibility=true 이면 Header Column 의 th 요소 하위에 button 요소로 생성됩니다.",
        "true 설정 + accessibility=false 이면 Header Column 의 th 요소 하위에 div 가 생성되고 그 하위에 button 요소로 생성됩니다.",
        "accessibility=true 이면 sortHeaderDiv 가 항상 true 로 동작합니다.",
        "true 로 설정 시 showSortableImage=true, sortEvent='onclick', sortedIconPosition='right' 로 강제 설정됩니다.",
        "sortHeaderDiv=true 이면 정렬 아이콘 영역이 button 요소로 렌더링되어 키보드 탭 이동 및 포커스를 지원하며, Enter 또는 Space 키로 정렬을 수행할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    //  - con_sortHeaderDiv / con_accessibility 가 미설정('') 이면 properties 에 키를 전달하지 않음
    //    (createCList 가 빈 문자열 value 를 자동 제외하므로 키 자체가 빠짐)
    //  - sortHeaderDiv 는 sortable=true 인 Header Column 에서만 효과가 있으므로 sortable: true 를 항상 포함
    let properties = {
        sortable: true,
        sortHeaderDiv: con_sortHeaderDiv.getValue(),
        accessibility: con_accessibility.getValue(),
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblSortHeaderDiv = con_sortHeaderDiv.getValue() === '' ? '미설정' : con_sortHeaderDiv.getValue();
    let lblAccessibility = con_accessibility.getValue() === '' ? '미설정' : con_accessibility.getValue();
    $c.gcm.createLabel('label="sortable=true, sortHeaderDiv=' + lblSortHeaderDiv + ', accessibility=' + lblAccessibility + ' 로 GridView 생성"', '', 'label1');

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // onsort 이벤트 부착 (정렬 수행 여부 검증용)
    let eList = $c.gcm.createEList(["onsort"]);

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



scwin.btn_checkDom_onclick = function (e) {
    // sortable Header Column 의 th 요소 DOM 구조 확인
    //  - sortHeaderDiv=false      : th > div.w2grid_head_sort_div_main > div
    //  - sortHeaderDiv=true, acc=T : th > button (직접)
    //  - sortHeaderDiv=true, acc=F : th > div.w2grid_head_sort_div_main_outer > button
    let headTable = document.querySelector("[id*='target1_head_table']");
    let headCell = headTable ? headTable.querySelector("th.w2grid_head_sortable") : null;

    if (headCell) {
        let directChild = headCell.firstElementChild;
        let directTag = directChild ? directChild.tagName.toLowerCase() : 'none';
        let hasButton = headCell.getElementsByTagName('button').length > 0;

        // 정렬 아이콘 렌더링 구조 한 줄로 출력
        let structure = '';
        if (directTag === 'button') {
            structure = 'th > button';
        } else if (directTag === 'div' && hasButton) {
            structure = 'th > div > button';
        } else if (directTag === 'div' && !hasButton) {
            structure = 'th > div > div';
        }
        wf_body_bottom.getObj("scwin").setReturnValue("정렬 아이콘 구조 : " + structure);
    }
}



scwin.btn_checkOption_onclick = function (e) {
    // sortHeaderDiv 효과(강제 옵션) 및 accessibility 강제 동작을 한 줄로 출력
    let opt = target1.options;
    // sortedIconPosition 기본값은 right. 미설정 시 옵션 값은 빈값('') 이지만 기본값 right 가 적용되어 아이콘은 우측에 표시됨
    let iconPos = opt.sortedIconPosition === '' ? '""(빈값 → 기본값 right 적용)' : opt.sortedIconPosition;
    wf_body_bottom.getObj("scwin").setReturnValue("sortHeaderDiv : " + opt.sortHeaderDiv + " / accessibility : " + opt.accessibility);
    wf_body_bottom.getObj("scwin").setReturnValue("showSortableImage : " + opt.showSortableImage + " / sortEvent : " + opt.sortEvent + " / sortedIconPosition : " + iconPos);
}



// onsort : sortable 헤더 클릭/더블클릭(또는 정렬 button 포커스 후 Enter/Space)으로 정렬방식이 변경되면 발생 → 정렬 수행 검증
scwin.target1_onsort = function () {
    let status = target1.getSortableStatus();
    if (status && status.length > 0) {
        let s = status[0];
        let dir = (String(s.sortOrder) === "1") ? "오름차순" : "내림차순";
        wf_body_bottom.getObj("scwin").setReturnValue("정렬 수행됨 (onsort) - colID : " + s.colID + " / sortOrder : " + s.sortOrder + " (" + dir + ")");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("정렬 수행됨 (onsort) - 정렬 초기화(해제)됨");
    }
};
